from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI(title="user-provider")


class UserIn(BaseModel):
    name: str


class User(BaseModel):
    id: int
    name: str
    active: bool


# Seed data: one active user so GET /users?active=true -> $[0].id == 1, active true
_SEED_USERS = [
    User(id=1, name="Grace", active=True),
    User(id=2, name="Linus", active=False),
]


def _get_store() -> dict[int, dict]:
    """Fresh store per call keeps tests isolated and deterministic."""
    return {u.id: u.model_dump() for u in _SEED_USERS}


_store: dict[int, dict] = {}


@app.on_event("startup")
def _reset_store() -> None:
    global _store
    _store = _get_store()


@app.get("/users")
def list_users(active: bool | None = None):
    users = list(_store.values())
    if active is not None:
        users = [u for u in users if u["active"] == active]
    # Stable ordering by id makes $[0] assertions deterministic.
    users.sort(key=lambda u: u["id"])
    return users


@app.get("/users/{user_id}")
def get_user(user_id: int):
    user = _store.get(user_id)
    if user is None:
        raise HTTPException(
            status_code=404, detail={"error": {"code": "not_found"}}
        )
    return user


@app.post("/users", status_code=201)
def create_user(payload: UserIn):
    new_id = max(_store, default=0) + 1
    user = User(id=new_id, name=payload.name, active=True)
    _store[new_id] = user.model_dump()
    return user
"})
